def run(_context):
    import json

    # List all parameters for Pocket Wall Finish, searching for stock/leave
    params = mb.list_params("Pocket Wall Finish")

    print("=== STOCK/LEAVE PARAMETERS ===")
    for k, v in params.items():
        k_lower = k.lower()
        if "stock" in k_lower or "leave" in k_lower:
            print(f"  {k}: {v['expression']}")

    # Also check depth/stepdown params
    print("\n=== DEPTH/STEPDOWN PARAMETERS ===")
    for k, v in params.items():
        k_lower = k.lower()
        if "depth" in k_lower or "stepdown" in k_lower or "multiple" in k_lower or "pass" in k_lower:
            print(f"  {k}: {v['expression']}")

    # Check height params
    print("\n=== HEIGHT PARAMETERS ===")
    for k, v in params.items():
        k_lower = k.lower()
        if "height" in k_lower or "top" in k_lower or "bottom" in k_lower:
            if "check" not in k_lower:  # skip the check sub-params
                print(f"  {k}: {v['expression']}")

